    public bool CanAutoLinkPendingFifa
    {
        get
        {
            if(_pendingFifa is null)return false;
            if(Careers.All(x=>x.SaveName.Contains("Demo",StringComparison.OrdinalIgnoreCase)))return true;
            if(CurrentCareer is null)return true;
            var activeSource=_db.GetSetting($"career:{CurrentCareer.Id}:fifa_source");var pendingSource=Path.GetFileName(_pendingFifa.SourcePath);
            var sourceChanged=!string.IsNullOrWhiteSpace(activeSource)&&!string.Equals(activeSource,pendingSource,StringComparison.OrdinalIgnoreCase);
            var playerChanged=!CurrentCareer.PlayerName.Contains(_pendingFifa.PlayerName,StringComparison.OrdinalIgnoreCase)&&!_pendingFifa.PlayerName.Contains(CurrentCareer.PlayerName,StringComparison.OrdinalIgnoreCase);
            var clubChanged=!string.Equals(CurrentCareer.Club,_pendingFifa.ClubName,StringComparison.OrdinalIgnoreCase);
            return sourceChanged&&(playerChanged||clubChanged);
        }
    }

    public void ReloadCareers(){Careers.Clear();foreach(var c in _db.GetCareers())Careers.Add(c);}
    public void CreateCareer(){if(string.IsNullOrWhiteSpace(NewPlayerName)||string.IsNullOrWhiteSpace(NewClub))throw new InvalidOperationException("Player name and club are required.");var id=_db.CreateCareer(NewSaveName,NewPlayerName,NewNationality,NewAge,NewClub,NewLeague,NewSeason,NewPosition,NewShirtNumber);ReloadCareers();CurrentCareer=Careers.Single(x=>x.Id==id);Status="Career created";}
    public void AddCharacter(){RequireCareer();if(string.IsNullOrWhiteSpace(CharacterName))throw new InvalidOperationException("Character name is required.");_db.AddCharacter(CurrentCareer!.Id,CharacterName,CharacterAge,CharacterNationality,CurrentCareer.Club,CharacterPosition,CharacterRole,Enum.Parse<CharacterType>(CharacterType));Refresh();Status=$"Added {CharacterName}";CharacterName="";}
    public void ProcessMatch()
    {
        RequireCareer();if(string.IsNullOrWhiteSpace(MatchOpponent))throw new InvalidOperationException("Opponent is required.");if(!DateTime.TryParse(MatchDate,out _))throw new InvalidOperationException("Enter a valid match date.");if(TeamScore<0||OpponentScore<0||Goals<0||Assists<0||Minutes is <0 or >130||Rating is <0 or >10)throw new InvalidOperationException("Check the score, statistics, minutes, and rating values.");
        var career=CurrentCareer!;var review=SelectedMatchReview;var importSnapshot=_loadedReviewSnapshot;var importingReview=_editingMatchId is null&&review is not null&&_loadedReviewId==review.Id&&importSnapshot?.LatestMatch?.EventKey==review.Review.EventKey;if(importingReview&&review!.Review.CareerId!=career.Id)throw new InvalidOperationException("This FIFA review belongs to another career. Reopen it from that career's Review Inbox.");if(importingReview&&PendingMatchReviews.Any(x=>x.Id!=review!.Id&&string.CompareOrdinal(x.Date,review.Date)<0))throw new InvalidOperationException("Import the oldest pending FIFA match first so cumulative statistics stay chronological.");
        if(importingReview&&!ScoreKnown&&InternationalMatch)throw new InvalidOperationException("Enter the exact final score before importing this international match. FIFA confirmed the appearance but did not expose the score.");
        var input=new MatchInput(MatchDate,MatchCompetition,MatchOpponent,MatchHome,TeamScore,OpponentScore,Started,Minutes,Goals,Assists,Rating,YellowCard,RedCard,PenaltyScored,PenaltyMissed,MatchNotes,string.IsNullOrWhiteSpace(MatchNextOpponent)?null:MatchNextOpponent,IsDerby,IsMajor,importingReview?StartedKnown:true,InternationalMatch?"International":"Club",InternationalMatch?(string.IsNullOrWhiteSpace(RepresentingTeam)?career.Nationality:RepresentingTeam):career.Club,ScoreKnown);
        var correcting=_editingMatchId is not null;var result=correcting?_careers.UpdateMatch(career.Id,_editingMatchId!.Value,input):_careers.ProcessMatch(career.Id,input,importingReview?"FIFA 18 Save":null,importingReview?importSnapshot!.LatestMatch!.EventKey:null);if(correcting)new PlayerPsychologyService(_db).RebuildBeforeMatch(career.Id,result.Match.Id);_db.CompleteMatchingFixture(career.Id,input.Date,input.Opponent);var media=AutoNews||AutoSocial?new MediaService(_db).GenerateDeterministic(career.Id,result.Events,AutoNews,AutoSocial):new MediaGenerationResult(0,0);var interview=new PostMatchInterviewService(_db).CreateIfEligible(career.Id,result,AutoPress);var world=new AutomaticWorldService(_db);var automatic=world.ApplyMatch(result,AutoTeammates,AutoManager,interview is not null,media.NewsItems>0,media.SocialPosts>0);if(correcting)world.RebuildMatchCharacterStates(career.Id);
        if(importingReview&&importSnapshot?.LatestMatch is not null){var eventKey=importSnapshot.LatestMatch.EventKey;_db.RecordProviderImport(career.Id,"FIFA 18 Save",eventKey,importSnapshot.SourcePath,importSnapshot.FileFingerprint,importSnapshot.CapturedAt,JsonSerializer.Serialize(importSnapshot.State));_db.CompleteProviderMatch(career.Id,"FIFA 18 Save",eventKey);_db.SetMatchReviewStatus(career.Id,"FIFA 18 Save",eventKey,"Imported");_db.MarkNotificationRead(career.Id,$"review:{eventKey}");_db.UpdateCareerFromProvider(career.Id,importSnapshot.PlayerName,importSnapshot.NationalityName,importSnapshot.Age,importSnapshot.ClubName,importSnapshot.LeagueName,importSnapshot.Season,importSnapshot.CurrentDate,importSnapshot.Position,importSnapshot.ShirtNumber);_db.SetSetting($"career:{career.Id}:fifa_player_id",importSnapshot.PlayerId.ToString());FifaSyncStatus="FIFA match imported. Watching for the next completed save.";_pendingFifa=null;_loadedReviewId=null;_loadedReviewSnapshot=null;SelectedMatchReview=null;ReloadMatchReviews();NotifyFifaState();ReloadCareers();_currentCareer=Careers.FirstOrDefault(x=>x.Id==career.Id)??career;OnChanged(nameof(CurrentCareer));}
        _editingMatchId=null;SelectedLoggedMatch=null;OnChanged(nameof(MatchSubmitLabel));OnChanged(nameof(MatchEditVisibility));MatchResultSummary=$"{(correcting?"Correction saved":"Saved")}. Generated {result.Events.Count} events and {automatic.IncomingMessages} incoming character reactions"+(interview is null?". No post-match interview requested.":". A post-match interview is waiting in the Press Room.")+(result.Narratives.Count>0?$" Active narratives: {string.Join(", ",result.Narratives)}.":"");Status=correcting?"Match corrected and world effects rebuilt":"World updated automatically";Refresh();
    }

