    public void CreateCareerFromPendingFifa()
    {
        if(_pendingFifa is null)throw new InvalidOperationException("Scan a FIFA save first.");
        var p=_pendingFifa;_db.Log("fifa_sync",$"Linking player={p.PlayerId}; career date={p.CurrentDate}.");
        var id=_db.CreateCareer(Path.GetFileName(p.SourcePath),p.PlayerName,p.NationalityName,p.Age,p.ClubName,p.LeagueName,p.Season,p.Position,p.ShirtNumber,p.CurrentDate);
        _db.UpdateCareerFromProvider(id,p.PlayerName,p.NationalityName,p.Age,p.ClubName,p.LeagueName,p.Season,p.CurrentDate,p.Position,p.ShirtNumber);_db.SetSetting($"career:{id}:fifa_player_id",p.PlayerId.ToString());ReloadCareers();CurrentCareer=Careers.Single(x=>x.Id==id);
        new AutomaticWorldService(_db).ApplyProgress(id,new(0,id,p.CapturedAt,p.CurrentDate,p.ClubName,p.LeagueName,p.Position,p.ShirtNumber,p.PlayerOverall,p.PlayerForm,p.PlayerInjuryKnown&&p.PlayerInjured,p.State.Appearances,p.State.Goals,p.State.Assists,p.State.YellowCards,p.State.RedCards,p.FileFingerprint),null);
        var supporting=SyncSupportingFacts(id,p);RecordFifaSync(p);
        if(p.LatestMatch is not null)
        {
            _db.StageMatchReview(id,"FIFA 18 Save",p.LatestMatch.EventKey,p.SourcePath,p.FileFingerprint,p.CapturedAt,JsonSerializer.Serialize(p.LatestMatch),JsonSerializer.Serialize(p));ReloadMatchReviews();SelectedMatchReview=PendingMatchReviews.FirstOrDefault(x=>x.Review.EventKey==p.LatestMatch.EventKey);
            if(!p.LatestMatch.RequiresReview&&p.LatestMatch.Confidence>=88){_loadedReviewId=SelectedMatchReview?.Id;_loadedReviewSnapshot=p;PopulateMatch(p.LatestMatch);ProcessMatch();}
            else _db.AddNotification(id,"Review","First FIFA match needs a baseline review",$"{p.LatestMatch.ScoreLabel} vs {p.LatestMatch.Opponent} is ready for review.","Review",85,$"review:{p.LatestMatch.EventKey}",DateTime.TryParse(p.CurrentDate,out var date)?date:p.CapturedAt);
        }
        FifaSyncStatus=$"Linked career created for {p.PlayerName}{DescribeSupportingSync(supporting,p)}"+(p.LatestMatch is null?". Waiting for the first completed appearance.":p.LatestMatch.RequiresReview?". One uncertain match is waiting in the Review Inbox.":". The first verified appearance was imported automatically.");Refresh();NotifyFifaState();
    }

    private Fifa18SupportingSyncResult SyncSupportingFacts(long careerId,Fifa18ParsedCareer parsed){var result=new Fifa18ImportService(_db).SyncSupportingFacts(careerId,parsed,AutoFifaSquadSync,AutoTeammates,AutoManager);Refresh();return result;}
    private static string DescribeSupportingSync(Fifa18SupportingSyncResult result,Fifa18ParsedCareer parsed){var parts=new List<string>();if(result.Squad is { } squad)parts.Add($"{parsed.Squad.Count} teammates synced ({squad.Added} new, {squad.MarkedInactive} departed)");if(result.FixtureUpdated&&parsed.NextFixture is { } fixture)parts.Add($"next fixture: {(fixture.IsHome?"vs":"at")} {fixture.Opponent}");return parts.Count==0?"":" | "+string.Join(" | ",parts);}

