    private void ReloadMatchReviews()
    {
        var selectedId=SelectedMatchReview?.Id;PendingMatchReviews.Clear();if(CurrentCareer is not null)foreach(var item in _db.GetMatchReviews(CurrentCareer.Id,"Pending"))PendingMatchReviews.Add(MatchReviewView.From(item));SelectedMatchReview=PendingMatchReviews.FirstOrDefault(x=>x.Id==selectedId)??PendingMatchReviews.FirstOrDefault();NotifyFifaState();
    }
    private void RebuildSquadViews()
    {
        var selectedId=SelectedSquadMember?.Id;SquadMembers.Clear();FormerTeammates.Clear();OtherCharacters.Clear();
        var teammates=Characters.Where(x=>x.Type==CareerCompanion.Core.Domain.CharacterType.Teammate).Select(SquadMemberView.From).ToList();
        foreach(var player in teammates.Where(x=>!x.Active))FormerTeammates.Add(player);
        IEnumerable<SquadMemberView> active=teammates.Where(x=>x.Active);
        active=SelectedSquadFilter switch
        {
            "Goalkeepers"=>active.Where(x=>x.Position=="GK"),
            "Defenders"=>active.Where(x=>new[]{"CB","LB","RB","LWB","RWB","SW"}.Contains(x.Position)),
            "Midfielders"=>active.Where(x=>new[]{"CDM","CM","CAM","LM","RM"}.Contains(x.Position)),
            "Forwards"=>active.Where(x=>new[]{"LW","RW","CF","ST"}.Contains(x.Position)),
            "Injured"=>active.Where(x=>x.Injured),
            _=>active
        };
        foreach(var player in active.OrderBy(x=>x.Position).ThenByDescending(x=>x.Overall))SquadMembers.Add(player);
        foreach(var character in Characters.Where(x=>x.Type!=CareerCompanion.Core.Domain.CharacterType.Teammate))OtherCharacters.Add(character);
        SelectedSquadMember=selectedId is null?null:SquadMembers.FirstOrDefault(x=>x.Id==selectedId);
        if(SelectedCharacter is not null&&!IsMessageCharacter(SelectedCharacter))SelectedCharacter=MessageCharacters.FirstOrDefault();
        OnChanged(nameof(PreMatchAvailability));OnChanged(nameof(PreMatchKeyPlayers));OnChanged(nameof(PreMatchIntel));OnChanged(nameof(MessageCharacters));
    }
    private bool IsMessageCharacter(Character character)
    {
        if(character.Type!=CareerCompanion.Core.Domain.CharacterType.Teammate)return true;
        if(character.Name.StartsWith("FIFA Player #",StringComparison.OrdinalIgnoreCase))return false;
        var playerId=CurrentCareer is null?null:_db.GetSetting($"career:{CurrentCareer.Id}:fifa_player_id");
        try{using var facts=JsonDocument.Parse(character.FactsJson);if(playerId is not null&&facts.RootElement.TryGetProperty("playerId",out var id)&&id.ToString()==playerId)return false;if(facts.RootElement.TryGetProperty("providerActive",out var active)&&active.ValueKind==JsonValueKind.False)return false;}catch(JsonException){}
        return true;
    }

