    public async Task SendMessageAsync(){RequireCareer();if(SelectedCharacter is null)throw new InvalidOperationException("Select a character first.");if(string.IsNullOrWhiteSpace(MessageText))return;MessageGenerationStatus="Generating in the background...";using var http=new HttpClient{Timeout=TimeSpan.FromSeconds(45)};var model=RouteModel(Events.FirstOrDefault()?.Importance??0,Enum.Parse<SceneType>(SelectedScene));var provider=CreateProvider(model);try{var service=new ConversationService(_db,provider);var scene=Enum.Parse<SceneType>(SelectedScene);var result=await service.SendAsync(CurrentCareer!.Id,SelectedCharacter.Id,scene,MessageText,model);MessageText="";if(result.Raw.StartsWith("offline-library:",StringComparison.Ordinal)){var reason=result.Raw["offline-library:".Length..];MessageGenerationStatus=$"{(reason=="offline-first"?"Offline reply":"Offline fallback")} | {model} | {reason}";}else MessageGenerationStatus=$"Reply received | {provider.Name} | {model} | "+(result.InputTokens+result.OutputTokens)+" tokens";LoadMessages();OnChanged(nameof(SelectedRelationship));NotifyImmersionState();}catch(LlmUnavailableException e){MessageGenerationStatus=e.Message;}catch(LlmRateLimitException e){MessageGenerationStatus=e.Message;}}
    public async Task RunAutomaticGenerationAsync(CancellationToken ct=default)
    {
        if(_automaticGenerationBusy||CurrentCareer is null)return;_automaticGenerationBusy=true;var careerId=CurrentCareer.Id;
        try
        {
            // Automatic reactions are first messages, so they are always the
            // grounded offline text created by AutomaticWorldService. Complete
            // any legacy rewrite jobs without spending a model request.
            foreach(var job in _db.GetPendingGenerationJobs(careerId,"automatic_reaction_llm",100))_db.CompleteGenerationJob(job.Id);
            MessageGenerationStatus="Automatic reactions use offline dialogue; AI is reserved for your questions.";
            await Task.CompletedTask;
        }
        finally{_automaticGenerationBusy=false;}
    }
    public async Task RecordPressAsync()
