        using var http=new HttpClient{Timeout=TimeSpan.FromSeconds(45)};var model=RouteModel(interview.Importance,SceneType.PressConference);var reply=await new PostMatchInterviewService(_db).GenerateReplyAsync(interview,question,answer,fallbackNext,CreateProvider(model),model);
        var careerTime=DateTime.TryParse(career.CurrentDate,out var parsedDate)?parsedDate:DateTime.UtcNow;var conv=_db.StartConversation(career.Id,journalist.Id,SceneType.PressConference,JsonSerializer.Serialize(new{interviewId=interview.Id,question}),careerTime);_db.AddMessage(conv,"journalist",question,careerTime);_db.AddMessage(conv,"user",answer,careerTime);_db.AddMessage(conv,"journalist",reply.JournalistResponse,careerTime);_db.AddMemory(career.Id,journalist.Id,null,$"Post-match statement: {answer}",Math.Clamp(interview.Importance,45,85),0,"post-match interview",false,careerTime);
        turns.Add(new(question,answer,reply.JournalistResponse,reply.AiGenerated));if(!complete)questions[next]=reply.JournalistResponse;_db.UpdatePostMatchInterviewDialogue(interview.Id,JsonSerializer.Serialize(questions),JsonSerializer.Serialize(turns),next,complete?"Completed":"Pending");if(complete)_db.MarkNotificationRead(career.Id,$"interview:{interview.MatchId}");new AutomaticWorldService(_db).ApplyPublicStatement(career.Id,interview.Id,interview.CurrentQuestion,answer,interview.Importance);PressAnswer="";OnChanged(nameof(PressAnswer));InterviewGenerationStatus=reply.AiGenerated?"Live journalist response generated":"Offline journalist fallback used";Status=complete?"Post-match interview completed":"Journalist asked a follow-up";ReloadInterview();Refresh();
    }
