    private ILlmProvider CreateProvider(string model){if(IsOllamaModel(model))return new OllamaProvider(new HttpClient{Timeout=TimeSpan.FromMinutes(3)},OllamaModel(model));if(IsCompatibleModel(model)){var env=Environment.GetEnvironmentVariable("COMPATIBLE_API_KEY");var stored=_db.GetSetting("compatible_api_key");if(string.IsNullOrWhiteSpace(stored)&&IsOpenRouterModel(model))stored=_db.GetSetting("openai_api_key");var key=!string.IsNullOrWhiteSpace(env)?env:(string.IsNullOrWhiteSpace(stored)?"":SecretStore.Unprotect(stored));var endpoint=IsOpenRouterModel(model)&&IsLocalCompatibleEndpoint(CompatibleEndpoint)?"https://openrouter.ai/api/v1":CompatibleEndpoint;return new OpenAICompatibleProvider(new HttpClient{Timeout=TimeSpan.FromMinutes(3)},endpoint,()=>key);}var claude=IsClaudeModel(model);var envKey=Environment.GetEnvironmentVariable(claude?"ANTHROPIC_API_KEY":"OPENAI_API_KEY");var storedKey=_db.GetSetting(claude?"anthropic_api_key":"openai_api_key");var openKey=!string.IsNullOrWhiteSpace(envKey)?envKey:(string.IsNullOrWhiteSpace(storedKey)?"":SecretStore.Unprotect(storedKey));if(string.IsNullOrWhiteSpace(openKey))return new OfflineLlmProvider();var http=new HttpClient{Timeout=TimeSpan.FromSeconds(45)};return claude?new ClaudeProvider(http,()=>openKey):new OpenAIProvider(http,()=>openKey);}
    private static bool IsOllamaModel(string model)=>model.StartsWith("ollama:",StringComparison.OrdinalIgnoreCase);
    private static bool IsCompatibleModel(string model)=>model.StartsWith("compatible:",StringComparison.OrdinalIgnoreCase);
    private static string CompatibleModel(string model)=>model["compatible:".Length..].Trim();
    private static string OllamaModel(string model)=>model["ollama:".Length..].Trim();
    private static bool IsClaudeModel(string model)=>model.StartsWith("claude-",StringComparison.OrdinalIgnoreCase);
    private string RouteModel(int importance,SceneType scene){var selected=PremiumRouting&&(importance>=75||scene is SceneType.Conflict or SceneType.TransferDiscussion)?PremiumModel:DefaultModel;return IsCompatibleModel(DefaultModel)&&!IsCompatibleModel(selected)?DefaultModel:selected;}
    private static bool IsOpenRouterModel(string model)=>model.StartsWith("compatible:openrouter/",StringComparison.OrdinalIgnoreCase)||model.Contains(":free",StringComparison.OrdinalIgnoreCase)&&model.StartsWith("compatible:",StringComparison.OrdinalIgnoreCase);
    private static bool IsLocalCompatibleEndpoint(string endpoint)=>endpoint.Contains("localhost:11434",StringComparison.OrdinalIgnoreCase)||endpoint.Contains("127.0.0.1:11434",StringComparison.OrdinalIgnoreCase);
    private void LoadSettings(){DefaultModel=_db.GetSetting("default_model")??Environment.GetEnvironmentVariable("OPENAI_DEFAULT_MODEL")??"compatible:openrouter/free";PremiumModel=_db.GetSetting("premium_model")??Environment.GetEnvironmentVariable("OPENAI_PREMIUM_MODEL")??"compatible:openrouter/free";CompatibleEndpoint=_db.GetSetting("compatible_endpoint")??Environment.GetEnvironmentVariable("COMPATIBLE_API_BASE_URL")??"https://openrouter.ai/api/v1";if((IsOpenRouterModel(DefaultModel)||IsOpenRouterModel(PremiumModel))&&IsLocalCompatibleEndpoint(CompatibleEndpoint))CompatibleEndpoint="https://openrouter.ai/api/v1";PremiumRouting=B("premium_routing",true);AutoTeammates=B("auto_teammates",true);AutoManager=B("auto_manager",true);AutoNews=B("auto_news",true);AutoSocial=B("auto_social",true);AutoPress=B("auto_press",true);DebugMode=B("debug_mode",false);AutoFifaWatch=B("auto_fifa_watch",true);AutoFifaSquadSync=B("auto_fifa_squad_sync",true);}
    private bool B(string key,bool fallback)=>bool.TryParse(_db.GetSetting(key),out var x)?x:fallback;
    private void RequireCareer(){if(CurrentCareer is null)throw new InvalidOperationException("Create or open a career first.");}
    private void LoadMessages(){Messages.Clear();if(CurrentCareer is null||SelectedCharacter is null)return;foreach(var m in _db.GetMessages(CurrentCareer.Id,SelectedCharacter.Id))Messages.Add(m);}
    private void ReloadInterview()
    {
        _activeInterview=CurrentCareer is null?null:_db.GetPendingPostMatchInterview(CurrentCareer.Id);var latestMatch=CurrentCareer is null?null:_db.GetMatches(CurrentCareer.Id,1).LastOrDefault();_latestInterview=latestMatch is null?null:_db.GetPostMatchInterview(CurrentCareer!.Id,latestMatch.Id);var shown=_activeInterview??_latestInterview;var questions=_activeInterview is null?[]:JsonSerializer.Deserialize<List<string>>(_activeInterview.QuestionsJson)??[];PressQuestion=_activeInterview is not null&&_activeInterview.CurrentQuestion<questions.Count?questions[_activeInterview.CurrentQuestion]:"No post-match interview is scheduled. Routine matches do not automatically generate media duties.";InterviewTranscript.Clear();if(shown is not null){var turns=ReadInterviewTurns(shown.AnswersJson);for(var i=0;i<turns.Count;i++){var turn=turns[i];if(i==0)InterviewTranscript.Add("JOURNALIST: "+turn.Question);InterviewTranscript.Add("YOU: "+turn.Answer);InterviewTranscript.Add("JOURNALIST: "+turn.JournalistResponse);}}OnChanged(nameof(PressQuestion));OnChanged(nameof(HasActiveInterview));OnChanged(nameof(InterviewVisibility));OnChanged(nameof(NoInterviewVisibility));OnChanged(nameof(InterviewCompleteVisibility));OnChanged(nameof(InterviewCompletionText));OnChanged(nameof(InterviewProgress));
    }
    private static List<InterviewTurn> ReadInterviewTurns(string json)
    {
        try{return JsonSerializer.Deserialize<List<InterviewTurn>>(json)??[];}catch(JsonException){try{return (JsonSerializer.Deserialize<List<string>>(json)??[]).Select(x=>new InterviewTurn("Previous question",x,"",false)).ToList();}catch(JsonException){return[];}}
    }
    public void Refresh(){Characters.Clear();MatchHistory.Clear();Fixtures.Clear();Events.Clear();News.Clear();Social.Clear();Notifications.Clear();ProgressSnapshots.Clear();DashboardItems.Clear();ReloadMatchReviews();if(CurrentCareer is null){RebuildSquadViews();NotifyFifaState();return;}_db.ResolveObsoleteNotifications(CurrentCareer.Id);foreach(var x in _db.GetCharacters(CurrentCareer.Id))Characters.Add(x);foreach(var x in _db.GetFixtures(CurrentCareer.Id))Fixtures.Add(x);foreach(var x in _db.GetNotifications(CurrentCareer.Id))Notifications.Add(x);foreach(var x in _db.GetCareerProgressSnapshots(CurrentCareer.Id))ProgressSnapshots.Add(x);RebuildSquadViews();if(SelectedCharacter is not null)SelectedCharacter=Characters.FirstOrDefault(x=>x.Id==SelectedCharacter.Id);foreach(var x in _db.GetEvents(CurrentCareer.Id))Events.Add(x);foreach(var x in _db.GetNews(CurrentCareer.Id))News.Add(x);foreach(var x in _db.GetSocial(CurrentCareer.Id))Social.Add(x);var matches=_db.GetMatches(CurrentCareer.Id,500);foreach(var match in matches.Reverse())MatchHistory.Add(match);if(SelectedLoggedMatch is not null)SelectedLoggedMatch=MatchHistory.FirstOrDefault(x=>x.Id==SelectedLoggedMatch.Id);var recent=matches.LastOrDefault();RecentMatchSummary=recent is null?"No matches logged":$"{recent.Input.ScoreLabel} vs {recent.Input.Opponent}";CurrentForm=matches.Count==0?"No form":string.Join("  ",matches.TakeLast(5).Select(m=>m.Result=="U"?"?":m.Result));foreach(var e in Events.Take(4))DashboardItems.Add($"{e.Type.Replace('_',' ')}: {e.Summary}");if(DashboardItems.Count==0)DashboardItems.Add("No activity yet. Log a match to bring the world alive.");DebugText=BuildDebug(matches);foreach(var name in new[]{nameof(RecentMatchSummary),nameof(CurrentForm),nameof(NextFixture),nameof(PlayerSummary),nameof(DebugText),nameof(SelectedCharacterSummary),nameof(SelectedRelationship),nameof(SelectedSquadRelationship),nameof(PreMatchOpponent),nameof(PreMatchMeta),nameof(PreMatchForm),nameof(PreMatchAvailability),nameof(PreMatchKeyPlayers),nameof(PreMatchIntel),nameof(PreMatchScouting),nameof(UnreadNotificationCount),nameof(NotificationBadge),nameof(NotificationNavLabel),nameof(LatestHeadline),nameof(LatestIncoming),nameof(ProgressSummary),nameof(SelectedMatchHistoryDetails),nameof(PlayerMindsetTitle),nameof(PlayerMindsetSummary),nameof(PlayerMindsetDetail),nameof(RecoveryChoiceVisibility)})OnChanged(name);NotifyFifaState();}
    private void NotifyImmersionState(){OnChanged(nameof(ManagerName));OnChanged(nameof(ManagerRelationship));OnChanged(nameof(ManagerBriefing));OnChanged(nameof(AgentName));}
    public string OpenSelectedNotification(){var item=SelectedNotification??throw new InvalidOperationException("Select a world update first.");_db.MarkNotificationRead(item.Id);var action=item.Action;if(action.StartsWith("Messages:",StringComparison.OrdinalIgnoreCase)&&long.TryParse(action.AsSpan("Messages:".Length),out var characterId)){SelectedCharacter=Characters.FirstOrDefault(x=>x.Id==characterId);action="Messages";}Refresh();return action;}
    public void MarkAllNotificationsRead(){if(CurrentCareer is null)return;_db.MarkAllNotificationsRead(CurrentCareer.Id);Refresh();Status="World updates marked as read";}
    public void ClearReadNotifications(){if(CurrentCareer is null)return;var removed=_db.ClearReadNotifications(CurrentCareer.Id);SelectedNotification=null;Refresh();Status=removed==1?"Cleared 1 read update":$"Cleared {removed} read updates";}
    private string BuildDebug(IReadOnlyList<CareerMatch> matches){if(CurrentCareer is null)return"No active career.";var sb=new StringBuilder();sb.AppendLine("RAW CAREER STATE").AppendLine(JsonSerializer.Serialize(CurrentCareer,new JsonSerializerOptions{WriteIndented=true})).AppendLine().AppendLine($"MATCHES: {matches.Count}  CHARACTERS: {Characters.Count}  EVENTS: {Events.Count}").AppendLine("\nRECENT EVENT IMPORTANCE / CLASSIFICATION");foreach(var e in Events.Take(20))sb.AppendLine($"{e.Importance,3} {e.Type,-24} {e.Classification} | {e.Summary}");sb.AppendLine("\nREACTION RULES: event >=25; news >=48; social >=55; press >=62; character relevance >=72.");if(SelectedCharacter is not null){var ranked=new CareerCompanion.Core.Simulation.MemoryRanker().Rank(_db.GetMemories(SelectedCharacter.Id),"recent match",DateTime.UtcNow);sb.AppendLine($"\nRETRIEVED MEMORIES FOR {SelectedCharacter.Name.ToUpperInvariant()}");foreach(var m in ranked)sb.AppendLine($"{m.Importance,3} {m.Topic}: {m.Text}");}return sb.ToString();}
}
